/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
from itertools import product
from unittest.mock import patch
import consumer

source = Path('summary.py').read_text()
variants = {
    'baseline': source,
    'remove code fallback': source.replace(\"record.get('code') or 'unknown'\", \"record['code']\"),
    'remove display-name fallback': source.replace(\"record.get('display_name') or record['name']\", \"record['display_name']\"),
    'remove negative guard': source.replace(\"    if amount < 0:\\n        raise ValueError('negative amount')\\n\", ''),
}
missing = object()
cases = []
for code, name, amount in product([missing, '', 'X'], [missing, '', 'A'], [-1, 0, 2]):
    record = {'name': 'Ada', 'amount': amount}
    if code is not missing:
        record['code'] = code
    if name is not missing:
        record['display_name'] = name
    expected = ('error', 'ValueError') if amount < 0 else ('value', (code if code is not missing and code else 'unknown', name if name is not missing and name else 'Ada', amount))
    cases.append((record, expected))
for label, candidate in variants.items():
    namespace = {}
    exec(compile(candidate, '<in-memory summary>', 'exec'), namespace)
    failures = []
    with patch.object(consumer, 'summarize', namespace['summarize']):
        for record, expected in cases:
            original = dict(record)
            try:
                actual = ('value', consumer.render(record))
            except Exception as error:
                actual = ('error', type(error).__name__)
            assert record == original, 'render mutated its input'
            if actual "'!= expected:
                failures.append((record, expected, actual))
    print(f'"'{label}: {len(cases) - len(failures)}/{len(cases)} contract cases passed')
    if failures:
        print('  example:', failures[0])
        if label == 'remove code fallback':
            print('  empty-code example:', next(f for f in failures if f[0].get('code') == '' and f[0]['amount'] >= 0))
PY"

